// 海报创建/更新的数据处理逻辑
import { ref } from 'vue'
import { useResponseMessage, useToast } from '@anteng/core'
import { createPoster, updatePoster } from '../../../../api/posterMarking'
import { base64src } from '../PosterBuilder/utils/tools'
import { $getWxacodeUnlimit } from '@anteng/core/src/api'
import { utmStore } from '../../../../stores'

interface posterItem {
  name: 'string'
  id: string
  isEdit?: boolean
  tenantId: string
  merchantId: string
  userId: string
  url: string
  qrcode: {
    x: number
    y: number
    size: number
    page: string
    // 选择商品时才存在
    goodsId: string
    utm: string
    // 选择分类时才存在
    faId: string
    childrenId: string
    // 选择资讯时才存在
    infId: string
  }
  createTime: string
  updateTime: object
  isDeleted: number
}

// 当前海报信息
export const editorPoster = ref<posterItem>({
  name: '',
  url: '',
  qrcode: {
    id: 0,
    x: 500,
    y: 500,
    size: 200,
    utm: '',
    page: ''
  }
})
// 二维码的base64
export const qrcodeImage = ref('')
// 二维码的本地url
export const qrCodeUrl = ref('')

// 错误时的二维码
export const errorQrCode =
  'data:image/png;base64,'
// 根据页面信息获取二维码
export const getQrcode = (code: string) => {
  const { env } = utmStore()
  return new Promise((resolve, reject) => {
    // 如果有传来的code,就用最新的code
    if (code) {
      if (!editorPoster.value?.qrcode) {
        editorPoster.value = {
          ...editorPoster.value,
          qrcode: { utm: code }
        }
      } else {
        editorPoster.value.qrcode.utm = code || editorPoster.value.qrcode?.utm
      }
      // 根据utm信息获取一下小程序码
      $getWxacodeUnlimit({
        // TODO page是写死的,他只是跳板页面
        page: 'pagesB/goodDetail/GoodDetail',
        scene: `utmCode=${code}`,
        env
      }).then(async res => {
        if (res.success) {
          qrcodeImage.value = `data:image/png;base64,${res.data}`
          // 需要将base64转成本地路径
          qrCodeUrl.value = await base64src(qrcodeImage.value)
          // 刷新
          return resolve()
        } else {
          console.log('获取小程序码失败:', res)
          useToast('获取小程序码失败，请重试')
          // 没有获取到小程序码
          qrcodeImage.value = errorQrCode
          return reject(res)
        }
      })
    } else {
      // 有utmCode
      // 根据utm信息获取一下小程序码
      $getWxacodeUnlimit({
        page: 'pagesB/goodDetail/GoodDetail',
        scene: `utmCode=${editorPoster.value?.qrcode?.utm}`,
        env
      }).then(async res => {
        if (res.success) {
          qrcodeImage.value = `data:image/png;base64,${res.data}`
          // 需要将base64转成本地路径
          qrCodeUrl.value = await base64src(qrcodeImage.value)
          // 刷新
          return resolve()
        } else {
          console.log('获取小程序码失败:', res)
          useToast('获取小程序码失败，请重试')
          // 没有获取到小程序码
          qrcodeImage.value = errorQrCode
          return reject(res)
        }
      })
    }
  })
}

// 提交 / 更新
export const submitData = (id?: string) => {
  if (id) {
    return new Promise((resolve, reject) => {
      updatePoster(id, editorPoster.value)
        .then(res => {
          if (res.success) {
            useToast('更新成功')
            // 更新成功后刷新二维码
            getQrcode(editorPoster.value?.qrcode?.utm)
              .then(() => resolve(res))
              .catch(e => {
                console.error('刷新二维码失败:', e)
                resolve(res)
              })
          } else {
            reject(res)
            useToast('更新失败')
          }
        })
        .catch(e => {
          useResponseMessage(e)
          reject(e)
        })
    })
  } else {
    return new Promise((resolve, reject) => {
      if (!editorPoster.value?.qrcode?.page) {
        useToast('请选择页面')
        return reject('用户未选择页面')
      }
      createPoster(editorPoster.value)
        .then(res => {
          if (res.success) {
            useToast('新建成功')
            // 新建成功后刷新二维码
            getQrcode(editorPoster.value?.qrcode?.utm)
              .then(() => resolve(res))
              .catch(e => {
                console.error('刷新二维码失败:', e)
                resolve(res)
              })
          } else {
            reject(res)
            useToast('新建失败')
          }
        })
        .catch(e => {
          useResponseMessage(e)
          reject(e)
        })
    })
  }
}
